/**
 * @file
 * @brief Utilities supporting operation on time data structures.
 *
 * POSIX defines gmtime() to convert from time_t to struct tm, but all
 * inverse transformations are non-standard or require access to time
 * zone information.  timeutil_timegm() implements the functionality
 * of the GNU extension timegm() function, workflow-free.
 */

#ifndef ZEPHYR_INCLUDE_SYS_TIMEUTIL_H_
#define ZEPHYR_INCLUDE_SYS_TIMEUTIL_H_

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <time.h>

#include <zephyr/sys/__assert.h>
#include <zephyr/sys/math_extras.h>
#include <zephyr/sys/time_units.h>
#include <zephyr/sys/util.h>
#include <zephyr/toolchain.h>

#ifdef __cplusplus
extern "C" {
#endif

/**
 * @defgroup timeutil_apis Time Utility APIs
 * @ingroup utilities
 * @defgroup timeutil_repr_apis Time Representation APIs
 * @ingroup timeutil_apis
 * @{
 */

/**
 * @brief Convert broken-down time to a POSIX epoch offset.
 *
 * Dates before 1970-01-01T00:00:00Z are not supported.
 *
 * @param tm pointer to broken-down time. Values are not normalized
 * or validated.
 *
 * @return the representation of the time with respect to the POSIX
 * epoch.  Behavior is undefined if the input does not correspond to a
 * valid calendar date after 1970-01-01.
 */
int64_t timeutil_timegm64(const struct tm *tm);

/**
 * @brief Convert broken-down time to a POSIX epoch offset.
 *
 * @param tm pointer to broken-down time.
 *
 * @return the representation of the time with respect to the POSIX
 * epoch, or (time_t)-1 if the time cannot be represented in a time_t
 * (and sets errno to ERANGE).
 */
time_t timeutil_timegm(const struct tm *tm);

/**
 * @}
 * @defgroup timeutil_sync_apis Time Synchronization APIs
 * @ingroup timeutil_apis
 * @{
 *
 * @brief APIs for disciplined time synchronization.
 *
 * These APIs support maintaining a correlation between two time
 * scales: a "local" clock typically driven by an inexpensive
 * crystal oscillator, and a "reference" clock driven by a high
 * accuracy source like GPS or NTP.
 */

/**
 * @brief Immutable state for synchronizing two clocks.
 *
 * Values required to convert durations between two time scales.
 *
 * @note The freshness of the translation and the capability of the
 * numeric representation imposes bounds on how long a synchronization
 * state can be used without overflowing during scaling operations.
 */
struct timeutil_sync_config {
	/** The nominal instance counter rate in Hz.
	 *
	 * This value is assumed to be precise, and may drift depending
	 * on the clock source.
	 *
	 * The value must be positive.
	 */
	uint32_t ref_Hz;

	/** The nominal local counter rate in Hz.
	 *
	 * This value is assumed to be inaccurate, but reasonably
	 * stable.
	 *
	 * The value must be positive.
	 */
	uint32_t local_Hz;
};

/**
 * @brief Representation of an instant in two time scales.
 *
 * Capturing the same instant in two time scales provides a
 * registration point that can be used to convert between those frame
 * of reference.
 */
struct timeutil_sync_instant {
	/** An instant in the reference time scale.
	 *
	 * This must never be zero in a valid timeutil_sync_instant
	 * object.
	 */
	uint64_t ref;

	/** The corresponding instant in the local time scale.
	 *
	 * A zero value is valid here.
	 */
	uint64_t local;
};

/**
 * @brief State required to convert instants between time scales.
 *
 * This state in conjunction with functions that manipulate it is
 * intended to be usable through a copy-update-swap pattern for
 * single-writer multi-reader use cases.
 */
struct timeutil_sync_state {
	/** Pointer to reference and local rate information. */
	const struct timeutil_sync_config *cfg;

	/** The base instant in both time scales. */
	struct timeutil_sync_instant base;

	/** The most recent instant in both time scales.
	 *
	 * This is captured here to provide data for skew calculation.
	 */
	struct timeutil_sync_instant latest;

	/** The scale factor used to correct for clock skew.
	 *
	 * The nominal rate for the local counter is assumed to be
	 * inaccurate creative to the reference counter.  A
	 * multiplicative scale factor corrects for the skew:
	 *
	 *   true_local_Hz = skew * local_Hz
	 *
	 * Initialize to zero or 1.0.  When zero, local_Hz is assumed to
	 * be accurate across timeutil_sync_ref_from_local() and
	 * timeutil_sync_local_from_ref().  Can be set from
	 * timeutil_sync_estimate_skew() or another mechanism.
	 */
	float skew;
};

/**
 * @brief Record a new instant in the time synchronization state.
 *
 * Note that this updates only the latest instant in the state; the
 * base instant and skew are not modified.  However, once at least two
 * instants have been recorded, the skew may be estimated and the
 * state updated to use it.
 *
 * @param tsp pointer to a timeutil_sync_state object.
 *
 * @param inst the new instant being recorded.  This becomes the
 * base instant if there is no base instant, otherwise the value must
 * be strictly after the current latest instant in both reference and
 * local time scales.
 *
 * @retval 0 if installation succeeded in providing a new base;
 * @retval 1 if installation provided a new latest instant;
 * @retval -EINVAL if the new instant is not compatible with the base
 * instant.
 */
int timeutil_sync_state_update(struct timeutil_sync_state *tsp,
			       const struct timeutil_sync_instant *inst);

/**
 * @brief Update the state with a new skew and possibly base value.
 *
 * Set the skew from a value retrieved from
 * timeutil_sync_estimate_skew() or through another mechanism.  If
 * base is also provided the base point is updated and the latest
 * point is cleared.
 *
 * @param tsp pointer to a timeutil_sync_state object.
 *
 * @param skew the skew to be used.  The value must be positive and
 * shouldn't be too far away from 1.0.
 *
 * @param base optional new base to be set.  If provided this becomes
 * the base instant and the latest instant is cleared.  This value can
 * normally be captured from `tsp->latest` prior to invoking this
 * function.
 *
 * @retval 0 if skew was updated
 * @retval -EINVAL if skew was not valid
 */
int timeutil_sync_state_set_skew(struct timeutil_sync_state *tsp, float skew,
				 const struct timeutil_sync_instant *base);

/**
 * @brief Estimate the skew based on current state.
 *
 * Using the base and latest instants from the state determine the
 * skew required of the local clock rate so the elapsed time matches
 * on both scales.
 *
 * @param tsp pointer to a timeutil_sync_state object.  Both base and
 * latest instants must be present, and the latest instant must be
 * after the base instant.
 *
 * @return the estimated skew factor, or zero if skew cannot be
 * estimated from the state.
 */
float timeutil_sync_estimate_skew(const struct timeutil_sync_state *tsp);

/**
 * @brief Interpolate a reference timescale instant from a local
 * instant.
 *
 * @param tsp pointer to a timeutil_sync_state object.  This must have
 * a base instant, a configuration, and a positive skew (which will be
 * treated as 1.0 if not initialized).
 *
 * @param local the instant measured in the local timescale.  This may
 * be before or after the base instant.
 *
 * @param refp where the corresponding instant in the reference
 * timescale should be stored.  A negative interpolation fails with no
 * store into this pointer.
 *
 * @retval 0 if interpolation succeeded using a unitary skew
 * @retval 1 if interpolation succeeded using a non-unitary skew
 * @retval -EINVAL if the state is not adequately initialized or
 * `refp` is null
 * @retval -ERANGE if the interpolated value would be negative or
 *otherwise cannot be represented.
 */
int timeutil_sync_ref_from_local(const struct timeutil_sync_state *tsp,
				 uint64_t local, uint64_t *refp);

/**
 * @brief Extrapolate a local timescale instant from a reference
 * instant.
 *
 * @param tsp pointer to a timeutil_sync_state object.  This must have
 * a base instant, a configuration, and a positive skew (which will be
 * treated as 1.0 if not initialized).
 *
 * @param ref the instant measured in the reference timescale.  This
 * may be before or after the base instant.
 *
 * @param localp where the corresponding instant in the local
 * timescale should be stored.  An interpolation that results in a
 * negative timestamp fails with no store through this pointer.
 *
 * @retval 0 if interpolation succeeded using a unitary skew
 * @retval 1 if interpolation succeeded using a non-unitary skew
 * @retval -EINVAL if the state is not adequately initialized or
 * `localp` is null
 * @retval -ERANGE if the interpolated value Cannot be represented.
 */
int timeutil_sync_local_from_ref(const struct timeutil_sync_state *tsp,
				 uint64_t ref, int64_t *localp);

/**
 * @brief Calculate the change in local rate from a skew.
 *
 * Given a skew factor, return the adjustment in parts-per-billion
 * needed to reconcile the real and nominal clock rates.
 *
 * A positive return value means that the local clock is running
 * faster than nominal: its actual frequency is greater than
 * `local_Hz`.  A negative return value means the local clock is
 * running slower than nominal.
 *
 * The returned value may be used to inform clock control hardware on
 * how to adjust the counter rate, or to display drift diagnostic
 * information.
 *
 * @param skew the skew factor
 *
 * @return the skew represented in parts-per-billion, or INT32_MIN if
 * the skew is outside the representable range.
 */
int32_t timeutil_sync_skew_to_ppb(float skew);

/**
 * @}
 * @defgroup timespec_util_apis Timespec Utility APIs
 * @ingroup timeutil_apis
 * @{
 */

/**
 * @brief Minimum representable value for `time_t`
 *
 * @note `time_t` is universally defined as a signed integer in Zephyr (usually `int64_t` or `long`),
 * although POSIX allows it to be floating-point as well.
 */
#define SYS_TIME_T_MIN ((((time_t)1 << (8 * sizeof(time_t) - 2)) - 1) * -2 - 1)

/**
 * @brief Maximum representable value for `time_t`
 *
 * @note `time_t` is universally defined as a signed integer in Zephyr (usually `int64_t` or `long`),
 * although POSIX allows it to be floating-point as well.
 */
#define SYS_TIME_T_MAX (~(time_t)0 ^ SYS_TIME_T_MIN)

/**
 * @brief Initialize a `timespec` object with seconds and nanoseconds.
 *
 * @note This macro simply initializes a `struct timespec` with the specified values and performs
 * no validation or normalization.
 *
 * @param sec the number of seconds.
 * @param nsec the number of nanoseconds.
 */
#define SYS_TIMESPEC(sec, nsec)                                                                    \
	((struct timespec){                                                                        \
		.tv_sec = (time_t)(sec),                                                           \
		.tv_nsec = (long)(nsec),                                                           \
	})

/**
 * @brief Initialize a `timespec` object to `0` seconds and `0` nanoseconds.
 */
#define SYS_TIMESPEC_ZERO SYS_TIMESPEC(0, 0)

/**
 * @brief Minimum representable `timespec` value
 *
 * The minimum value is `{.tv_sec = SYS_TIME_T_MIN, .tv_nsec = 0}`.
 */
#define SYS_TIMESPEC_MIN SYS_TIMESPEC(SYS_TIME_T_MIN, 0)

/**
 * @brief Maximum representable `timespec` value
 *
 * The maximum value is `{.tv_sec = SYS_TIME_T_MAX, .tv_nsec = NSEC_PER_SEC - 1}`.
 */
#define SYS_TIMESPEC_MAX SYS_TIMESPEC(SYS_TIME_T_MAX, NSEC_PER_SEC - 1)

/**
 * @brief Convert a kernel timeout to a `timespec`.
 *
 * This macro converts a kernel timeout (i.e. `k_timeout_t`) to a `struct timespec`.
 *
 * @note This macro will assert if the timeout is not relative.
 *
 * @param timeout the kernel timeout to convert.
 * @param ts pointer to the `timespec` object to store the result.
 */
static inline void timespec_from_timeout(k_timeout_t timeout, struct timespec *ts)
{
	__ASSERT_NO_MSG(ts != NULL);
	/* Need an equivalent of K_TIMEOUT_IS_RELATIVE(timeout) */
	__ASSERT_NO_MSG(!Z_IS_TIMEOUT_RELATIVE(timeout) ? K_TIMEOUT_EQ(timeout, K_FOREVER) ||
							  K_TIMEOUT_EQ(timeout, K_NO_WAIT)
							: true);

	if (K_TIMEOUT_EQ(timeout, K_FOREVER)) {
		*ts = SYS_TIMESPEC_MAX;
	} else if (K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
		*ts = SYS_TIMESPEC_ZERO;
	} else {
		uint64_t ns = k_ticks_to_ns_ceil64(timeout.ticks);

		*ts = SYS_TIMESPEC(ns / NSEC_PER_SEC, ns % NSEC_PER_SEC);
	}
}

/**
 * @brief Convert a `timespec` to a kernel timeout.
 *
 * This function converts a duration represented as a `struct timespec` to a kernel timeout
 * object (i.e. `k_timeout_t`), saturating to `K_NO_WAIT` for negative durations, rounding up to
 * the nearest tick on intermediate values, and saturating to `K_Ticks_MAX` (or `K_FOREVER` if equal
 * to `SYS_TIMESPEC_MAX`) if the duration exceeds the maximum representable timeout.
 *
 * @param req pointer to the `timespec` object to convert.
 * @param rem optional pointer to a `timespec` object to store the remainder of the division.
 * @return the corresponding kernel timeout.
 */
static inline k_timeout_t timespec_to_timeout(const struct timespec *req, struct timespec *rem)
{
	k_timeout_t timeout;
	struct timespec temp = SYS_TIMESPEC_ZERO;

	__ASSERT_NO_MSG((req != NULL) && timespec_is_valid(req));

	if (timespec_compare(req, &temp) <= 0) {
		if (rem != NULL) {
			*rem = *req;
		}
		return K_NO_WAIT;
	}

	temp = SYS_TIMESPEC_MAX;
	if (timespec_equal(req, &temp)) {
		if (rem != NULL) {
			*rem = SYS_TIMESPEC_ZERO;
		}
		return K_FOREVER;
	}

	uint64_t ns = 0;
	uint64_t sec_ns = 0;
	uint64_t max_ticks = COND_CODE_1(CONFIG_TIMEOUT_64BIT, (INT64_MAX), (UINT32_MAX - 1));
	uint64_t max_ns = k_ticks_to_ns_floor64(max_ticks);

	if (u64_mul_overflow(req->tv_sec, NSEC_PER_SEC, &sec_ns) ||
	    u64_add_overflow(req->tv_nsec, sec_ns, &ns) || ns > max_ns) {
		/* Saturate to max ticks */
		timeout.ticks = max_ticks;
	} else {
		/* Round up to the next tick boundary */
		timeout.ticks = k_ns_to_ticks_ceil64(ns);
	}

	if (rem != NULL) {
		*rem = *req;
		timespec_from_timeout(timeout, &temp);
		timespec_sub(rem, &temp);
	}

	return timeout;
}

/**
 * @brief Check if a `timespec` is valid
 *
 * Determines if a `timespec` object is valid (i.e. normalized) by checking that the `.tv_nsec`
 * field is in the range `[0, NSEC_PER_SEC)`.
 *
 * @param ts pointer to the `timespec` object to validate.
 * @return `true` if the `timespec` is valid, `false` otherwise.
 */
static inline bool timespec_is_valid(const struct timespec *ts)
{
	__ASSERT_NO_MSG(ts != NULL);

	return (ts->tv_nsec >= 0) && (ts->tv_nsec < NSEC_PER_SEC);
}

/**
 * @brief Normalize a `timespec` object
 *
 * Normalizes a `timespec` object so that the `tv_nsec` field is in the half-open range
 * `[0, NSEC_PER_SEC)`. This is achieved by converting any excess nanoseconds (positive or
 * negative) into whole seconds and adding or subtracting them from `tv_sec`.
 *
 * @param ts pointer to the `timespec` object to normalize.
 * @return `true` if the `timespec` is successfully normalized, `false` if normalization failed
 * due to integer overflow or underflow.
 */
static inline bool timespec_normalize(struct timespec *ts)
{
	__ASSERT_NO_MSG(ts != NULL);

#if defined( CONFIG_SPEED_OPTIMIZATIONS ) && ( !defined( __GNUC__ ) || defined( __clang__ ) )
	/*
	 * Clang does not follow the GCC convention for signed integer division, where the remainder
	 * has the same sign as the dividend. Instead, it uses a branchless approach which may
	 * produce incorrect results in some cases. Avoid that by doing manual division with loops.
	 */
	while (ts->tv_nsec >= (long)NSEC_PER_SEC) {
		if (ts->tv_sec == SYS_TIME_T_MAX) {
			return false;
		}
		ts->tv_sec += 1;
		ts->tv_nsec -= NSEC_PER_SEC;
	}

	while (ts->tv_nsec < 0) {
		if (ts->tv_sec == SYS_TIME_T_MIN) {
			return false;
		}
		ts->tv_sec -= 1;
		ts->tv_nsec += NSEC_PER_SEC;
	}

	return true;
#else
	long sec;

	if (ts->tv_nsec >= (long)NSEC_PER_SEC) {
		sec = ts->tv_nsec / (long)NSEC_PER_SEC;
	} else if (ts->tv_nsec < 0) {
		sec = (unsigned long)-(ts->tv_nsec + 1) / (long)NSEC_PER_SEC + 1;
		sec = -sec;
	} else {
		sec = 0;
	}

	if ((sec > 0) && (SYS_TIME_T_MAX - ts->tv_sec < sec)) {
		/*
		 * When `ts->tv_nsec >= (long)NSEC_PER_SEC` and `sec > 0`, adding `sec` to
		 * `ts->tv_sec` would overflow `SYS_TIME_T_MAX`.
		 */
		return false;
	}

	if ((sec < 0) && (ts->tv_sec < SYS_TIME_T_MIN - sec)) {
		/*
		 * When `ts->tv_nsec < 0` and `sec < 0`, subtracting `sec` from `ts->tv_sec` would
		 * underflow `SYS_TIME_T_MIN`.
		 */
		return false;
	}

	ts->tv_nsec -= (long)NSEC_PER_SEC * sec;
	ts->tv_sec += sec;

	return true;
#endif
}

/**
 * @brief Add one `timespec` to another
 *
 * This function adds two `timespec` objects (`a` and `b`) and stores the normalized result back
 * into `a` without corrupting `a` if an overflow or underflow occurs.
 *
 * @param a pointer to the first `timespec` object, where the result will be stored.
 * @param b pointer to the second `timespec` object to add to `a`.
 * @return `true` if the addition is successful, `false` if an overflow or underflow occurred.
 */
static inline bool timespec_add(struct timespec *a, const struct timespec *b)
{
	__ASSERT_NO_MSG((a != NULL) && timespec_is_valid(a));
	__ASSERT_NO_MSG((b != NULL) && timespec_is_valid(b));

	struct timespec c = *a;

	if ((c.tv_sec > 0) && (b->tv_sec > 0) && (SYS_TIME_T_MAX - c.tv_sec < b->tv_sec)) {
		/* Positive overflow */
		return false;
	}

	if ((c.tv_sec < 0) && (b->tv_sec < 0) && (SYS_TIME_T_MIN - c.tv_sec > b->tv_sec)) {
		/* Negative underflow */
		return false;
	}

	c.tv_sec += b->tv_sec;
	c.tv_nsec += b->tv_nsec;

	if (!timespec_normalize(&c)) {
		return false;
	}

	*a = c;

	return true;
}

/**
 * @brief Negate a `timespec` object
 *
 * Negates a `timespec` object in-place without corrupting the object if an overflow occurs.
 *
 * @param ts pointer to the `timespec` object to negate.
 * @return `true` if the negation is successful, `false` if an overflow occurred.
 */
static inline bool timespec_negate(struct timespec *ts)
{
	__ASSERT_NO_MSG((ts != NULL) && timespec_is_valid(ts));

	struct timespec c = *ts;

#if defined( CONFIG_SPEED_OPTIMIZATIONS ) && ( !defined( __GNUC__ ) || defined( __clang__ ) )
	if ((c.tv_sec == SYS_TIME_T_MIN) && (c.tv_nsec == 0)) {
		/*
		 * `-SYS_TIME_T_MIN` is `SYS_TIME_T_MAX + 1`, which cannot be represented.
		 * However, if `c.tv_nsec > 0`, then normalizing the result will borrow one second
		 * from `c.tv_sec`, bringing it back within the representable range.
		 */
		return false;
	}

	if (c.tv_sec == SYS_TIME_T_MIN) {
		/*
		 * Manually adjust `c` to avoid integer overflow on `-c.tv_sec` when
		 * `c.tv_sec == SYS_TIME_T_MIN` and `c.tv_nsec > 0`.
		 */
		c.tv_sec = SYS_TIME_T_MAX;
		c.tv_nsec = (long)NSEC_PER_SEC - c.tv_nsec;
		*ts = c;
		return true;
	}

	c.tv_sec = -c.tv_sec;
	c.tv_nsec = -c.tv_nsec;
#else
	if (u64_mul_overflow((uint64_t)c.tv_sec, (uint64_t)-1, (uint64_t *)&c.tv_sec)) {
		/*
		 * Note cleanly that `-SYS_TIME_T_MIN` in two's complement arithmetic is still
		 * `SYS_TIME_T_MIN`.
		 */
	}
	c.tv_nsec = -c.tv_nsec;
	if (c.tv_sec == SYS_TIME_T_MIN) {
		if (c.tv_nsec == 0) {
			return false;
		}
		c.tv_sec = SYS_TIME_T_MAX;
		c.tv_nsec += NSEC_PER_SEC;
		*ts = c;
		return true;
	}
#endif
	if (!timespec_normalize(&c)) {
		return false;
	}

	*ts = c;

	return true;
}

/**
 * @brief Subtract one `timespec` from another
 *
 * This function subtracts the `timespec` object `b` from `a` and stores the normalized result
 * back into `a` without corrupting `a` if an overflow or underflow occurs.
 *
 * @param a pointer to the first `timespec` object, where the result will be stored.
 * @param b pointer to the second `timespec` object to subtract from `a`.
 * @return `true` if the subtraction is successful, `false` if an overflow or underflow occurred.
 */
static inline bool timespec_sub(struct timespec *a, const struct timespec *b)
{
	__ASSERT_NO_MSG((a != NULL) && timespec_is_valid(a));
	__ASSERT_NO_MSG((b != NULL) && timespec_is_valid(b));

	struct timespec neg_b = *b;

	if (!timespec_negate(&neg_b)) {
		return false;
	}

	return timespec_add(a, &neg_b);
}

/**
 * @brief Compare two `timespec` objects
 *
 * This function compares two `timespec` objects (`a` and `b`).
 *
 * @param a pointer to the first `timespec` object.
 * @param b pointer to the second `timespec` object.
 * @return `-1` if `a < b`, `0` if `a == b`, and `1` if `a > b`.
 */
static inline int timespec_compare(const struct timespec *a, const struct timespec *b)
{
	__ASSERT_NO_MSG((a != NULL) && timespec_is_valid(a));
	__ASSERT_NO_MSG((b != NULL) && timespec_is_valid(b));

	if (a->tv_sec == b->tv_sec) {
		return (a->tv_nsec < b->tv_nsec) ? -1 : ((a->tv_nsec > b->tv_nsec) ? 1 : 0);
	}

	return (a->tv_sec < b->tv_sec) ? -1 : 1;
}

/**
 * @brief Check if two `timespec` objects are equal
 *
 * This function checks if two `timespec` objects (`a` and `b`) have strictly identical
 * `.tv_sec` and `.tv_nsec` fields.
 *
 * @note Notice that valid comparison does not require normalization.
 *
 * @param a pointer to the first `timespec` object.
 * @param b pointer to the second `timespec` object.
 * @return `true` if the two `timespec` objects are equal, `false` otherwise.
 */
static inline bool timespec_equal(const struct timespec *a, const struct timespec *b)
{
	__ASSERT_NO_MSG(a != NULL);
	__ASSERT_NO_MSG(b != NULL);

	return (a->tv_sec == b->tv_sec) && (a->tv_nsec == b->tv_nsec);
}

/**
 * @}
 */

#ifdef __cplusplus
}
#endif

#endif /* ZEPHYR_INCLUDE_SYS_TIMEUTIL_H_ */
